function povAnchors(rec) {
  try {
    const p = rec?.initial?.balls
      ?.find((b) => b.id === recCueId(rec))?.state?.pos; // GH-383
    const phi = Number(rec?.shot?.phi);
    if (!p || ![p.x, p.y, p.z, phi].every(Number.isFinite)) return null;
    const dx = Math.cos(phi), dy = Math.sin(phi);
    return {
      ti: povTImpact(rec), d: [dx, dy],
      addrCam: [p.x - 1.05 * dx, p.y - 1.05 * dy, p.z + 0.36],
      addrLook: [p.x + 1.40 * dx, p.y + 1.40 * dy, p.z],
      standCam: [p.x - 1.75 * dx, p.y - 1.75 * dy, 0.81],
      standLook: [0, 0, 0.02],
    };
  } catch { return null; }
}

